let toastTimer;
function toast(message){const el=document.getElementById('toast');el.innerHTML=`${icon('check',16)}<span>${e(message)}</span>`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function openModal(title,body){if(gameMode)Game.cancelWalk();const modal=document.getElementById('modal');modal.className='';modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">${icon('close',17)}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){document.getElementById('modal').close();}
function celebrate(){const colors=['#adc48a','#e8cd7f','#c4afd4','#dca889'];for(let i=0;i<22;i++){const piece=document.createElement('i');piece.className='confetti-piece';piece.style.left=`${5+Math.random()*90}%`;piece.style.background=colors[i%colors.length];piece.style.animationDelay=`${Math.random()*.4}s`;piece.style.setProperty('--drift',`${Math.random()*160-80}px`);document.body.append(piece);setTimeout(()=>piece.remove(),2700);}}
function showTask(id){
  const t=state.tasks.find(t=>t.id===id);if(!t)return;
  const action=t.status==='available'?button('我和家长说好了，接下委托','accept-task',`data-id="${id}"`,'primary full'):t.status==='accepted'?button('我已在现实中完成，告诉家长','submit-task',`data-id="${id}"`,'primary full'):['submitted','confirmed'].includes(t.status)?button('请家长来看一眼','parent-for-task',`data-id="${id}"`,'secondary full'):button('安排这笔努力赚来的钱','go-close','data-view="market"','primary full');
  openModal(e(t.name),`<div class="modal-illustration warm">${taskArt(t)}</div><div class="between"><h3>完成后，报酬是 ¥${money(t.amount)}</h3>${pill(statusLabel[t.status],t.status==='paid'?'soft':'gold')}</div><p class="mt16">${e(t.detail)}。开始前，和家长确认完成标准。做完后再回来提交，不用拍照上传。</p><div class="confirmation-box">${t.status==='available'?'这是一项可以选择的额外委托。报酬与要求都应该提前说好。':t.status==='accepted'?'你已经接下啦。接下来离开屏幕，去完成生活里的小事吧。':t.status==='submitted'?'已经告诉家长，正在等待检查。确认完成、兑现报酬后，钱包才会增加。':t.status==='confirmed'?'家长已确认你的努力，报酬还在等待兑现，尚未计入可用零钱。':'这份努力已经变成你自己的钱。现在可以为它作一次选择。'}</div>${action}`);
}
function showAgreement(){
  openModal('我们家的小小约定',`<div class="modal-illustration warm">${Art.mascot(100)}</div><h3 class="center">说好的事情，我们一起认真做到。</h3><div class="rule-row"><span>我怎样得到本金？</span><strong>在现实中劳动，家长确认并兑现报酬</strong></div><div class="rule-row"><span>理财收益谁来给？</span><strong>家长提前预留，按约结算后可领取</strong></div><div class="rule-row"><span>收益也能继续存吗？</span><strong>可以，先确认下一期条件与预算</strong></div><div class="rule-row"><span>想提前取回来？</span><strong>本金取回，按约定活期示例利率重算收益</strong></div><div class="rule-row"><span>家长改了新利率？</span><strong>已经存好的一期不受影响</strong></div><div class="rule-row"><span>预算不够了？</span><strong>暂不接新计划，已有承诺照常履行</strong></div><p class="tiny muted mt16">当前家庭约定年利率 ${fixedRate()}，仅作教学示例，不是银行报价。产品在 APP 中模拟，资金由家长保管并实际交付。</p><div class="mt24">${button('我知道啦','close-modal','','primary full')}</div>`);
}
function showProduct(key){
  const p=Products[key];if(!p)return;
  if(p.type==='preview')return showClassroom(key);
  if(p.type==='income')return openModal(p.name,`<div class="modal-illustration">${Art.tree('annual')}</div>${pill('家庭收益分配教学计划','purple')}<h3 class="mt16">收益的去向，由孩子决定</h3><p class="small muted mt16">30 天一期，本期约定年化收益率 ${fixedRate()}，收益由家长承担；10 元起。它是家庭教学计划，不是公募基金。</p><div class="rule-row"><span>现金分红</span><strong>收益入零钱，本金同条件续期</strong></div><div class="rule-row"><span>红利再投</span><strong>本金和收益一起同条件续期</strong></div><div class="confirmation-box">每期先结算，再检查下一期预算。预算不足或利率变更时，本息留在钱包，重新确认后再安排。提前取回按约定示例活期利率重算。</div>${button('我来选一种方式','buy','data-product="dividend"','primary full')}<div class="mt16">${link('认识真实基金的分红与除息','dividend-lesson','data-mode="cash"')}</div>`);
  openModal(p.name,`<div class="modal-illustration">${Art.tree(key)}</div><div class="between">${pill(p.tag)}${pill('家长按约兑现','gold')}</div><h3 class="mt16">${p.subtitle}</h3><div class="rule-row"><span>本期家庭约定年利率</span><strong>${fixedRate()}</strong></div><div class="rule-row"><span>等待多久？</span><strong>${p.days} 天后到期</strong></div><div class="rule-row"><span>从多少开始？</span><strong>${money(p.minimum)} 元</strong></div><div class="rule-row"><span>怎么计算本期收益？</span><strong>本金 × 年利率 × 天数 ÷ 365</strong></div><div class="rule-row"><span>怎样体验复利？</span><strong>到期结算后，把本金与收益一起续存</strong></div><div class="confirmation-box">到期前显示的是<strong>预计收益</strong>。结算后才进入钱包。提前取回按家庭约定的本期利率与示例活期年利率 0.10% 的较低值重算，本金不会因此被扣罚。</div><p class="tiny muted">这是参照定期存款机制设计的家庭计划。期限、起存金额与利率为教学约定，不对应某家银行当前在售产品。</p><div class="mt24">${button('存一笔我的钱','buy',`data-product="${key}"`,'primary full')}</div>`);
}
function showBuy(key,amount,mode='buy'){
  const p=Products[key];if(!p||!['fixed','income'].includes(p.type))return;
  const initial=amount??Math.min(state.wallet,Math.max(p.minimum,2000));
  const expected=Money.interest(initial,state.rateBps,p.days);
  openModal(mode==='reinvest'?'让本金和收益，一起继续长':`存入${p.name}`,`<div class="between">${pill(p.tag)}<span class="small muted">零钱钱包 ¥${money(state.wallet)}</span></div><form data-form="buy" novalidate><input name="product" type="hidden" value="${key}"><input name="mode" type="hidden" value="${mode}"><div class="number-label mt24">这次，想留下多少？</div><div class="amount-input"><span>¥</span><input aria-label="存入金额" name="amount" type="text" inputmode="decimal" value="${money(initial).replaceAll(',','')}" autocomplete="off" data-input="purchase"></div><div class="amount-chips">${[1000,2000,5000].map(n=>`<button type="button" class="amount-chip" data-action="amount-chip" data-amount="${n}">${n/100} 元</button>`).join('')}<button type="button" class="amount-chip" data-action="amount-chip" data-amount="${state.wallet}">全部零钱</button></div><div class="rule-row"><span>本期家庭约定年利率</span><strong>${fixedRate()}</strong></div><div class="rule-row"><span>预计到期日</span><strong>${Day.add(state.now,p.days)}</strong></div><div class="rule-row"><span>本期预计收益</span><strong class="green">+¥<span id="buy-profit">${money(expected)}</span></strong></div><div class="rule-row"><span>本期到期本息</span><strong>¥<span id="buy-total">${money(initial+expected)}</span></strong></div><div class="confirmation-box">家长会为这期预留 <strong id="buy-reserve">${money(expected)}</strong> 元收益预算。<br>预计收益到期后才结算，资金在家庭中保管。</div>${p.type==='income'?distributionChoices(state.distribution):''}<label class="check-row"><input type="checkbox" name="agree"><span>${p.type==='income'?'我同意按所选方式同条件续期；新利率或预算不足时先回钱包。':''}我和家长已确认本期约定，也知道提前取回会按规则重算收益。</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">${mode==='reinvest'?'确认本息续存':'确认存入'}</button></form>`);
}
function updateBuy(){const form=document.querySelector('form[data-form="buy"]');if(!form)return;const amount=Money.parse(form.elements.amount.value)||0;const product=Products[form.elements.product.value];const profit=Money.interest(amount,state.rateBps,product.days);document.getElementById('buy-profit').textContent=money(profit);document.getElementById('buy-total').textContent=money(amount+profit);document.getElementById('buy-reserve').textContent=money(profit);}
function showBuySuccess(p){openModal('一份努力，已经好好存下',`<div class="modal-illustration">${Art.tree(p.product)}</div><div class="receipt-total">¥${money(p.principal)}</div><p class="center">${Products[p.product].name} · ${Day.label(p.end)}到期</p><div class="confirmation-box">本期预计收益 <strong>¥${money(p.expected)}</strong>，家长已按约预留。到期结算后，可以领取，也可以继续存入新一期。</div><div class="dual-buttons">${button('先回小镇','go-close','data-view="home"','ghost')}${button('看看我的持有','go-close','data-view="holdings"','primary')}</div>`);celebrate();}
function showMaturity(p){if(Products[p.product].type==='income')return openModal('这一次分红，按你的选择',`<div class="modal-illustration warm">${Art.mascot(105)}</div><div class="receipt-total">+¥${money(p.expected)}</div><p class="center">家长按本期约定结算收益 · ${p.distribution==='cash'?'现金分红':'红利再投'}</p><div class="confirmation-box">${p.renewalId?(p.distribution==='cash'?`收益 ${money(p.expected)} 元进入零钱，本金 ${money(p.principal)} 元继续下一期。`:`收益加入本金，${money(p.renewalPrincipal)} 元已进入下一期。`):p.renewalMessage}<br>实际领取仍需申请并由家长交付。</div>${button('查看我的持有','go-close','data-view="holdings"','primary full')}<div class="mt16">${link('查看零钱与还款安排','go-close','data-view="loans"')}</div>`);openModal('这份努力，多长出了一点',`<div class="modal-illustration warm">${Art.mascot(105)}</div><p class="center">${Products[p.product].name}按约到期，本息已回到零钱钱包</p><div class="receipt-total">¥${money(p.principal+p.expected)}</div><div class="receipt-detail"><span>原本金 ¥${money(p.principal)}</span><span class="green">已结算收益 +¥${money(p.expected)}</span></div><div class="confirmation-box">这笔收益由家长按约兑现。把它和原本金一起留下，下一期参与计算的钱就更多了。<br><strong>续存前会先检查新一期条件与预算。</strong></div><div class="dual-buttons">${button('先留在钱包','close-modal','','ghost')}${button('把本息一起续存','reinvest',`data-product="${p.product}" data-amount="${p.principal+p.expected}"`,'primary')}</div><p class="tiny muted center mt16">也可以稍后在钱包里申请实际领取。</p>`);celebrate();}
function showHolding(id){
  const p=state.positions.find(p=>p.id===id&&p.status==='active');if(!p)return;
  const elapsed=Math.max(0,Math.min(p.days,Day.difference(p.start,state.now)));const accrued=Money.interest(p.principal,p.rateBps,elapsed);
  openModal(`${Products[p.product].name}的本期约定`,`<div class="modal-illustration">${Art.tree(p.product)}</div><div class="rule-row"><span>本金</span><strong>¥${money(p.principal)}</strong></div><div class="rule-row"><span>开始与到期</span><strong>${p.start}<br>${p.end}</strong></div><div class="rule-row"><span>本期年利率</span><strong>${(p.rateBps/100).toFixed(2)}%</strong></div><div class="rule-row"><span>已走过的时间</span><strong>${elapsed} / ${p.days} 天</strong></div><div class="rule-row"><span>按持有时间展示的应计收益</span><strong>¥${money(accrued)} · 尚未结算</strong></div><div class="rule-row"><span>到期预计收益</span><strong>¥${money(p.expected)} · 家长已预留</strong></div><div class="confirmation-box">应计展示不是已经拿到的钱，收益也没有每天自动加入本金。本期利息到期后结算；选择本息续存，才进入下一期本金。</div>${Products[p.product].type==='income'?`<div class="mt16">${button(p.distribution==='cash'?'当前现金分红，修改方式':'当前红利再投，修改方式','distribution',`data-id="${id}"`,'secondary full')}</div>`:''}${button('需要提前取回？','redeem-info',`data-id="${id}"`,'ghost full')}`);
}
function showRedeem(id){const p=state.positions.find(p=>p.id===id&&p.status==='active');if(!p)return;const elapsed=Math.max(0,Day.difference(p.start,state.now));const profit=Money.interest(p.principal,Math.min(10,p.rateBps),elapsed);openModal('提前取回，也要按约定来',`<div class="modal-illustration warm">${icon('clock',70)}</div><p>可以提前取回本金。根据这份家庭约定，收益将按本期约定利率与 0.10% 的较低值，结合已持有天数重算。</p><div class="rule-row"><span>可取回本金</span><strong>¥${money(p.principal)}</strong></div><div class="rule-row"><span>按约提前取回收益</span><strong>¥${money(profit)}</strong></div><div class="rule-row"><span>如持有到期预计收益</span><strong>¥${money(p.expected)}</strong></div><div class="confirmation-box">现在需要用钱，也是一种选择。先看懂取舍，再决定。</div><div class="dual-buttons">${button('我再想想','holding-detail',`data-id="${id}"`,'ghost')}${button('确认提前取回','redeem-confirm',`data-id="${id}"`,'primary')}</div>`);}
function showWithdraw(purpose='我的小小计划'){
  const initial=Math.min(state.wallet,1000);
  openModal('把一笔零钱，带到生活里',`<div class="between">${pill('可用零钱')}<strong>¥${money(state.wallet)}</strong></div><form data-form="withdraw" novalidate><div class="number-label mt24">这次想领取</div><div class="amount-input"><span>¥</span><input name="amount" aria-label="领取金额" type="text" inputmode="decimal" value="${money(initial).replaceAll(',','')}"></div><div class="field"><label for="withdraw-purpose">想用它做什么？</label><input id="withdraw-purpose" name="purpose" value="${e(purpose)}" maxlength="50" autocomplete="off"></div><div class="confirmation-box">申请后，这笔钱先进入<strong>待领取</strong>，不能再重复安排。家长实际交付并确认后，才计为已经领取。持有中的本金要先按约取回。</div><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">把领取申请交给家长</button></form>`);
}
function showPayTask(id){const t=state.tasks.find(t=>t.id===id&&t.status==='confirmed');if(!t)return;openModal('兑现这份真实的努力',`<div class="modal-illustration warm">${taskArt(t)}</div><h3 class="center">${e(t.name)}</h3><div class="receipt-total">¥${money(t.amount)}</div><p>确认前，请先实际交付报酬，或明确在家庭中为孩子预留代管这笔钱。确认后，报酬计入孩子的可用钱包。</p><form data-form="pay-task" novalidate><input type="hidden" name="id" value="${id}"><label class="check-row mt24"><input type="checkbox" name="delivered"><span>我已实际交付，或已为孩子预留代管这笔劳动报酬。</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">确认报酬已兑现</button></form>`);}
function showPayRequest(id){const r=state.requests.find(r=>r.id===id&&r.status==='pending');if(!r)return;openModal('确认实际交付这笔钱',`<div class="modal-illustration warm">${icon('wallet',70)}</div><div class="receipt-total">¥${money(r.amount)}</div><p class="center">${e(r.purpose)}</p><div class="confirmation-box">请先通过现金或家庭约定的方式实际交付。确认后，这笔钱才从孩子账户总资产中扣除；不会再次扣减收益预算。</div><form data-form="pay-request" novalidate><input name="id" type="hidden" value="${id}"><label class="check-row"><input type="checkbox" name="delivered"><span>我已向孩子实际交付这笔钱。</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">确认已实际领取</button></form>`);}
function showNewTask(){openModal('和孩子商量一个新委托',`<form data-form="new-task" novalidate><div class="form-grid"><div class="field"><label for="task-name">这次做什么？</label><input id="task-name" name="name" placeholder="例如：一起整理换季衣物" maxlength="30" autocomplete="off"></div><div class="field"><label for="task-pay">提前约定的报酬（元）</label><input id="task-pay" name="amount" value="8.00" inputmode="decimal"><small>任务限于适龄、安全的家庭活动。完成标准由亲子事前说明。</small></div></div><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">放进孩子的委托板</button></form>`);}
function showGoal(){openModal('给心里的愿望，写个名字',`<div class="modal-illustration purple">${Art.telescope()}</div><form data-form="goal" novalidate><div class="form-grid"><div class="field"><label for="goal-name">我想攒钱做什么？</label><input id="goal-name" name="name" value="${e(state.goalName||'第一架天文望远镜')}" maxlength="24"></div><div class="field"><label for="goal-amount">目标金额（元）</label><input id="goal-amount" name="amount" inputmode="decimal" value="${money(state.goal).replaceAll(',','')}"></div></div><p class="tiny muted mt16">愿望可以变。调整目标不会改变已经赚到的钱，也不影响正在履行的产品约定。</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">保存我的小愿望</button></form>`);}
function showClassroom(key){
  if(key==='money')return openModal('零钱基金 · 产品课堂',`<div class="modal-illustration">${icon('leaf',75)}</div>${pill('只认识规则，不动用劳动本金','neutral')}<h3 class="mt16">收益会变化，结转也有自己的规则</h3><p class="mt16">货币基金不是银行存款，也不保证盈利或最低收益。收益如何分配、何时成为新份额，要看具体基金的正式规则。</p><div class="rule-row"><span>每天看到收益</span><strong>不等于每天已经到账或复利</strong></div><div class="rule-row"><span>看到近期年化指标</span><strong>不能当作未来收益承诺</strong></div><div class="confirmation-box">我们家还没有约定这类产品的结转方式和亏损承担。等把规则说清楚，再决定是否加入可以兑现的家庭计划。</div>${button('先看看已有的家庭计划','go-close','data-view="market"','primary full')}<div class="mt16">${button('认识现金分红与红利再投','dividend-lesson','data-mode="cash"','secondary full')}</div>`);
  const values=[100,104,98,94,105,108,112];
  const chart=values.map((v,i)=>`${i?'L':'M'}${25+i*62} ${140-(v-90)*4}`).join(' ');
  openModal('森林指数 · 产品课堂',`<div class="between">${pill('虚构路径，只用于观察','purple')}<span class="tiny muted">100 份 × 净值</span></div><h3 class="mt16">上涨和下跌，都可能发生</h3><div class="trend-amount" id="preview-value">¥100.00</div><p id="preview-change" class="small muted">起点：100 份，每份净值 1.00 元</p><svg viewBox="0 0 430 170" style="width:100%;margin:18px 0" aria-label="示例净值先涨后跌再上涨的路径"><path d="M20 145H415" stroke="#e6e4ee"/><path d="${chart}" fill="none" stroke="#a193b5" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle id="preview-marker" cx="25" cy="100" r="5" fill="#8e7aa6" stroke="#fff" stroke-width="2"/></svg><label class="small muted" for="market-path">拖动看看不同阶段</label><input id="market-path" data-input="market-path" type="range" min="0" max="6" value="0" style="width:100%;accent-color:#a18bb9;margin:15px 0"><div class="confirmation-box" id="preview-message">持有份额不变，净值变化会让持仓价值变化。它不是固定利息，也不保证长期一定赚钱。</div><p class="tiny muted">这里没有买入操作，不影响劳动本金。家长兑现范围、亏损承担、费用与分红再投资规则尚未约定。</p><div class="mt24">${button('我认识这种变化了','close-modal','','primary full')}</div>`);
}
function renderControls(){
  const names={A:'绘本小镇',B:'冒险路线',C:'零花钱手账'};const audit=Engine.check(state);
  document.getElementById('prototype-controls').innerHTML=`<div class="prototype-switcher" aria-label="原型首页方案切换"><button data-action="variant-prev" aria-label="上一个首页方案">${icon('back',16)}</button><span class="variant-label"><small>首页方案</small>${variant} · ${names[variant]}</span><button data-action="variant-next" aria-label="下一个首页方案">${icon('chevron',16)}</button></div><button class="proto-tools-button" data-action="tools" aria-label="打开原型演示面板">${icon('settings',15)}<span>演示面板</span></button>${toolsOpen?`<aside class="demo-drawer"><div class="between"><h3>原型演示面板</h3><button class="icon-btn" data-action="tools" aria-label="收起演示面板">${icon('close',16)}</button></div><p>这里的日期推进仅用于演示状态，产品内的实际期限不会加速。示例数据仅在当前页面内存中。</p><div class="actions">${button('演示至最近到期','demo-maturity','','secondary')}${button('演示下一天','demo-day','','ghost')}${button('演示至下次还款日','demo-payday','','ghost')}${button('切到劳动待确认','demo-review','','ghost')}${button('体验预算不足','demo-low-budget','','ghost')}${button('回到初始家庭','demo-reset','','ghost')}${button('完整体验怎么走','demo-guide','','ghost')}${!view.startsWith('parent')?button(gameMode?'查看界面原型':'进入2.5D小镇','game-mode','','ghost'):''}</div><div class="demo-state"><span>演示日期 <b>${state.now}</b></span><span>总资产 <b>${money(Engine.assets(state))}</b></span><span>可用预算 <b>${money(Engine.budgetFree(state))}</b></span><span>账目核对 <b>${Object.values(audit).slice(0,3).every(Boolean)?'一致':'需检查'}</b></span></div><details><summary class="small muted">查看完整演示状态</summary><pre>${e(JSON.stringify({当前孩子校验:audit,家庭各自校验:family.children.map(c=>({孩子:c.child,...Engine.check(c)})),家庭状态:family},null,2))}</pre></details></aside>`:''}`;
}
function changeVariant(step){const keys=['A','B','C'];variant=keys[(keys.indexOf(variant)+step+3)%3];const url=new URL(location.href);url.searchParams.set('variant',variant);url.searchParams.set('screen','home');history.replaceState(null,'',url);view='home';closeModal();render();window.scrollTo(0,0);console.info('Prototype layout and state',{variant,state:structuredClone(state),audit:Engine.check(state)});}
function advanceDemo(days){const result=Family.advance(family,days).find(r=>r.profileId===state.profileId);render();toast(result.message);if(result.matured.length)showMaturity(result.matured[0]);}
document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;if(target.type==='submit'&&target.form)return;event.preventDefault();const action=target.dataset.action,id=target.dataset.id;
  if(action==='go')return go(target.dataset.view);
  if(action==='go-close'){closeModal();return go(target.dataset.view);}
  if(action==='close-modal')return closeModal();
  if(action==='task-filter'){taskFilter=target.dataset.filter;return render();}
  if(action==='task-detail')return showTask(id);
  if(action==='accept-task'||action==='submit-task'){const r=Engine.task(state,id,action==='accept-task'?'accept':'submit');render();showTask(id);return toast(r.message);}
  if(action==='parent-for-task'){closeModal();return go('parent-tasks');}
  if(action==='approve-task'){const r=Engine.task(state,id,'approve');render();return toast(r.message);}
  if(action==='pay-task')return showPayTask(id);
  if(action==='new-task')return showNewTask();
  if(action==='product')return showProduct(target.dataset.product);
  if(action==='buy')return showBuy(target.dataset.product);
  if(action==='reinvest')return showBuy(target.dataset.product,Number(target.dataset.amount),'reinvest');
  if(action==='amount-chip'){const form=target.closest('form');form.elements.amount.value=(Number(target.dataset.amount)/100).toFixed(2);return updateBuy();}
  if(action==='holding-detail')return showHolding(id);
  if(action==='redeem-info')return showRedeem(id);
  if(action==='redeem-confirm'){const r=Engine.redeem(state,id);closeModal();render();return toast(r.message);}
  if(action==='agreement')return showAgreement();
  if(action==='withdraw')return showWithdraw(target.dataset.purpose||'我的小小计划');
  if(action==='pay-request')return showPayRequest(id);
  if(action==='edit-goal')return showGoal();
  if(action==='weekly-plan'){state.weeklyPlan=Number(target.dataset.amount);return render();}
  if(action==='tools'){toolsOpen=!toolsOpen;return renderControls();}
  if(action==='variant-prev')return changeVariant(-1);
  if(action==='variant-next')return changeVariant(1);
  if(action==='demo-day')return advanceDemo(1);
  if(action==='demo-maturity'){const days=Engine.nextMaturity(state);return days===null?toast('先在理财小屋存一笔钱，再看看它到期的样子。'):advanceDemo(days);}
  if(action==='demo-reset'){resetFamily();taskFilter='all';go('home');return toast('已经回到初始示例家庭。');}
  if(action==='demo-review'){resetFamily();state.tasks[0].status='submitted';go('parent-tasks');return toast('已载入劳动待确认的演示场景。');}
  if(action==='demo-low-budget'){resetFamily();state.budget=Engine.reserved(state);go('market');showBuy('sprout',2000);return toast('已载入预算都被现有承诺占用的场景。');}
  if(action==='demo-guide')return openModal('建议这样体验完整故事',`<div class="timeline mt16"><div class="timeline-item"><h4>1. 孩子接下劳动委托</h4><p>在劳动页接取、完成后提交，等待家长确认。</p></div><div class="timeline-item"><h4>2. 家长确认并兑现报酬</h4><p>进入家长空间，先确认完成，再确认报酬已交付或预留代管。</p></div><div class="timeline-item"><h4>3. 孩子把一笔钱存起来</h4><p>选择家庭计划，输入金额，确认约定后存入。</p></div><div class="timeline-item"><h4>4. 演示产品到期与本息续存</h4><p>用本面板推进示例时间，结算后选择本息再投，观察下一期本金与预算变化。</p></div><div class="timeline-item"><h4>5. 申请领取，家长兑现</h4><p>孩子在钱包申请，家长确认实际交付；账本完整记录。</p></div></div>${button('从劳动委托开始','go-close','data-view="tasks"','primary full')}`);
  if(action==='notifications')return openModal('小镇里的新消息',`<div class="confirmation-box">${pendingTasks().length?`有 <strong>${pendingTasks().length}</strong> 项劳动等待家长处理。`:'暂时没有待确认的劳动。'}<br>${pendingRequests().length?`有 <strong>${pendingRequests().length}</strong> 笔领取申请等待实际交付。`:'暂时没有领取申请。'}</div>${button('看看家长空间','go-close','data-view="parent"','secondary full')}`);
});
document.addEventListener('submit',event=>{
  const form=event.target;if(!form.dataset.form)return;event.preventDefault();const data=new FormData(form),type=form.dataset.form;const error=message=>{form.querySelector('.form-error').textContent=message;};let result;
  if(type==='buy'){
    if(!data.has('agree'))return error('先和家长确认这份约定，再勾选确认。');
    result=Engine.buy(state,data.get('product'),Money.parse(data.get('amount')),data.get('distribution')||state.distribution);if(!result.ok)return error(result.message);render();return showBuySuccess(result.position);
  }
  if(type==='withdraw'){result=Engine.request(state,Money.parse(data.get('amount')),data.get('purpose'));if(!result.ok)return error(result.message);closeModal();render();return toast(result.message);}
  if(type==='pay-task'||type==='pay-request'){
    if(!data.has('delivered'))return error('请先确认实际交付或按说明预留，再勾选。');
    result=type==='pay-task'?Engine.task(state,data.get('id'),'pay'):Engine.payRequest(state,data.get('id'));if(!result.ok)return error(result.message);closeModal();render();toast(result.message);if(type==='pay-task')celebrate();return;
  }
  if(type==='new-task'){result=Engine.addTask(state,data.get('name'),Money.parse(data.get('amount')));if(!result.ok)return error(result.message);closeModal();render();return toast(result.message);}
  if(type==='settings'){result=Engine.settings(state,Money.parse(data.get('budget')),Money.parse(data.get('rate')),data.get('child'));if(!result.ok)return error(result.message);render();return toast(result.message);}
  if(type==='goal'){
    const amount=Money.parse(data.get('amount')),name=data.get('name').trim();if(!name||name.length>24)return error('给愿望写一个 1–24 个字的名字吧。');if(amount===null||amount<100||amount>1000000)return error('目标金额请设在 1–10000 元之间，最多保留两位小数。');state.goal=amount;state.goalName=name;closeModal();render();return toast('愿望已更新，已有的积累和约定都保留。');
  }
});
function updateProjection(){
  const points=projectionData(),last=points[points.length-1];const chart=document.querySelector('.chart-wrap');if(!chart)return;chart.innerHTML=projectionChart(points);const strongs=document.querySelectorAll('.growth-split strong');strongs[0].textContent=`¥${money(last.reinvest)}`;strongs[1].textContent=`+¥${money(last.reinvest-last.simple)}`;
  const tag=document.querySelector('.two-columns>section.card .between .pill');if(tag)tag.textContent=`${projectionYears} 年后`;
  const note=document.querySelector('.two-columns>section.card>p.tiny');if(note)note.textContent=`仅为假设投影：把当前全部积累投入，每年按 ${fixedRate()} 结算并续存${projectionContribute?`，每年末再投入 ${money(state.weeklyPlan*52)} 元计划劳动所得`:''}。收益取出方案也计入已取出的收益。未来利率、收入与预算可能变化，投影不计入当前资产，也不代表家长已承诺未来兑付。`;
}
document.addEventListener('input',event=>{
  const type=event.target.dataset.input;
  if(type==='purchase')updateBuy();
  if(type==='projection'){projectionYears=Number(event.target.value);updateProjection();}
  if(type==='market-path'){const index=Number(event.target.value),value=[100,104,98,94,105,108,112][index];document.getElementById('preview-value').textContent=`¥${value.toFixed(2)}`;document.getElementById('preview-change').textContent=`第 ${index+1} 段示例 · 100 份 × 净值 ${(value/100).toFixed(2)} 元`;const marker=document.getElementById('preview-marker');marker.setAttribute('cx',25+index*62);marker.setAttribute('cy',140-(value-90)*4);document.getElementById('preview-message').textContent=value<100?`这时的持仓比起点少了 ${(100-value).toFixed(2)} 元。亏损可能发生，长期持有也不保证盈利。`:'持有份额不变，净值变化会让持仓价值变化。它不是固定利息，也不保证长期一定赚钱。';}
});
document.addEventListener('change',event=>{if(event.target.dataset.input==='contribution'){projectionContribute=event.target.checked;updateProjection();}});
document.addEventListener('keydown',event=>{if(document.body.classList.contains('landscape-required')||gameMode&&!view.startsWith('parent'))return;if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||event.target.closest('[contenteditable]')||document.getElementById('modal').open)return;if(event.key==='ArrowLeft'){event.preventDefault();changeVariant(-1);}if(event.key==='ArrowRight'){event.preventDefault();changeVariant(1);}});
document.getElementById('modal').addEventListener('click',event=>{if(event.target===event.currentTarget){const rect=event.currentTarget.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
window.addEventListener('popstate',()=>{const q=new URLSearchParams(location.search);gameMode=q.get('mode')!=='app';variant=['A','B','C'].includes(q.get('variant'))?q.get('variant'):'A';const next=q.get('screen')||'home';if(!next.startsWith('parent'))parentUnlocked=false;if(next.startsWith('parent')&&!parentUnlocked){view='home';render();showAccess('parent',next);}else{view=next;render();}});
window.__prototype={snapshot:()=>structuredClone(state),audit:()=>Engine.check(state),family:()=>structuredClone(family),scene:()=>({mode:gameMode,profileId:state.profileId,pose:structuredClone(Game.local()),walking:!!Game.frame,zoom:Game.zoom,pan:{...Game.pan},night:Game.night,panel:Game.panel,activePlace:Game.activePlace})};
const initialView=view;if(view.startsWith('parent'))view='home';render();if(initialView.startsWith('parent'))showAccess('parent',initialView);
